class Literal64Sign(unittest.TestCase):
    def test_translator_matches_gfx1030(self):
        with tempfile.TemporaryDirectory(prefix="lit64_") as work:
            for name, body, want in CASES:
                with self.subTest(name):
                    case = int_hw_probe.Case("lit64", name, body)
                    self.assertEqual(int_hw_probe._translate_case(work, case), want)


if __name__ == "__main__":
    unittest.main()
